const LS_ROCKET_PERSIST_KEY = 'ailongshort-ls-rocket-emojis-v1';
const LS_ROCKET_CAP = 500;
/** 구조 로켓 캔들 마커 — 별도 OFF 없이 항상 표시(마커 레이어 칩과 무관) */
