  /** 심볼/TF 바뀔 때 이전 /api/market 요청 취소 — 느린 응답이 새 차트를 덮어쓰지 않게 */
  const marketFetchAbortRef = useRef<AbortController | null>(null);
  const [candles, setCandles] = useState<Candle[]>([]);
