            channelBandScreen: poly,
            x1: minPx,
            y1: minPy,
            x2: maxPx,
            y2: maxPy,
            xMaxRight: maxPx,
            priceStripRight,
            chartWidth: rect.width,
            chartHeight: rect.height,
