          const t2n = o.time2 != null ? Number(o.time2) : t1n;
          if (!Number.isFinite(t1n)) continue;
          const loT = Math.min(t1n, t2n);
          const hiT = Math.max(t1n, t2n);
          if (curBarTime < loT || curBarTime > hiT) continue;
          const lbl = String(o.label || '');
